<script lang="ts">
 import {onMount} from 'svelte';import {api} from '@/shared/client-api';import {ErrorMessage} from './ui';import {LinkedText} from './linked-text';
 type Theater={id:string;name:string;status:string};type Support={id:string;theater:string;title:string;description:string;type:string;status:string;version:number};
 let theaters:Theater[]=[];let support:Support[]=[];let busy=false;let error='';
 const statuses:Record<string,string>={new:'Neu',review:'In Prüfung',planned:'Geplant',doing:'In Bearbeitung',done:'Abgeschlossen',closed:'Geschlossen'};
 async function load(){busy=true;error='';try{[theaters,support]=await Promise.all([api<Theater[]>('/api/platform/tenants'),api<Support[]>('/api/platform/support')]);}catch(e){error=e instanceof Error?e.message:'Laden fehlgeschlagen.';}finally{busy=false;}}
 async function toggle(theater:Theater){const status=theater.status==='active'?'disabled':'active';if(!confirm(status==='disabled'?`„${theater.name}“ sperren? Bestehende Theaterzugänge werden gesperrt.`:`„${theater.name}“ wieder freigeben?`))return;busy=true;try{await api('/api/platform/tenants',{method:'PATCH',body:JSON.stringify({id:theater.id,status})});await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function update(item:Support,status:string){busy=true;try{await api('/api/platform/support',{method:'PATCH',body:JSON.stringify({id:item.id,version:item.version,status})});await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
<section class="surface"><div class="section-heading"><h2>Theater verwalten</h2><button class="button secondary" disabled={busy} on:click={load}>Aktualisieren</button></div><p class="muted">Eine Sperre entzieht auch bestehenden Sitzungen den Zugang zu diesem Theater.</p><ErrorMessage message={error}/>{#each theaters as theater(theater.id)}<div class="detail-row"><strong>{theater.name}</strong><span>{theater.status==='active'?'Aktiv':'Gesperrt'}</span><button class="button secondary" disabled={busy} on:click={()=>void toggle(theater)}>{theater.status==='active'?'Theater sperren':'Freigeben'}</button></div>{/each}</section>
<section class="surface"><h2>Plattform-Support</h2><p class="muted">Hier erscheinen ausschließlich Rückmeldungen, die ihre Verfasser ausdrücklich weitergegeben haben.</p>{#if !support.length}<p>Keine eingereichten Supportanfragen.</p>{/if}{#each support as item(item.id)}<article class="feedback-row"><div class="feedback-row-content"><strong>{item.title}</strong><p class="small muted">{item.theater} · {item.type==='bug'?'Fehler':'Idee'}</p><LinkedText text={item.description}/></div><label>Status<select aria-label={'Status von '+item.title} value={item.status} disabled={busy} on:change={e=>void update(item,e.currentTarget.value)}>{#each Object.entries(statuses) as [key,label](key)}<option value={key}>{label}</option>{/each}</select></label></article>{/each}</section>
